using Cultivation.Domain;
using Cultivation.Simulation;
using Cultivation.Persistence;
internal static class R2SectCommandsTests
{
    private static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    private static WorldState World(){var w=LifeEventScenario.Create();w.SectDuty=null;w.TestProcurement=null;WorldPeriodFixture.Reset(w);int n=w.Characters.FindIndex(c=>c.Id=="player");var a=w.Characters[n];w.Characters[n]=a with {DemoLocationId="sect",HexPosition=RegionGeometry.Resolve(w.HexMap!,a,"sect")};w.SectWorkAssignments.RemoveAll(x=>x.ActorId=="player"&&x.ProductId=="herb");w.Ledger.Add(new(w.NextSequence++,0,"sect-test-herbs","$genesis","sect","herb",10,"Genesis"));w.Ledger.Add(new(w.NextSequence++,0,"sect-test-money","$genesis","player","spirit-stone",30,"Genesis"));return w;}
    private static ActionIntent Cmd(string id,ActionKind k,string item,long n=1)=>new(id,"player","sect",item,n,0,DecisionSource.Player,k);
    public static IEnumerable<(string Name,Action Body)> Cases=>new (string,Action)[]{
        ("R2 contribution purchase defers transfer and resumes through stores",()=>{var e=new SimulationEngine(World());var i=Cmd("points",ActionKind.BuyContribution,"spirit-stone",10);long funds=Inventory.Balance(e.Snapshot(),"player","spirit-stone"),points=Inventory.Balance(e.Snapshot(),"player","contribution");e.Submit(i);e.AdvanceTo(0);var w=e.Snapshot();var a=w.Time!.ActionRuntime!.Actions[i.Id];Check(a.Phase==ActionPhase.Running&&Inventory.Balance(w,"player","spirit-stone")==funds,"Payment early");string dir=Path.Combine(Path.GetTempPath(),"r2-sect-command-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{foreach(IWorldStore store in new IWorldStore[]{new JsonWorldStore(),new SqliteWorldStore()}){string p=Path.Combine(dir,store.GetType().Name);store.Save(p,w);var x=new SimulationEngine(w);var y=new SimulationEngine(store.Load(p));x.AdvanceTo(a.DueAt);y.AdvanceTo(a.DueAt);var d=y.Snapshot();Check(WorldCodec.Digest(x.Snapshot())==WorldCodec.Digest(d)&&d.Time!.ActionRuntime!.Actions[i.Id].Phase==ActionPhase.Completed&&Inventory.Balance(d,"player","spirit-stone")==funds-10&&Inventory.Balance(d,"player","contribution")==points+10,"Purchase mismatch");}}finally{foreach(string p in Directory.GetFiles(dir))File.Delete(p);Directory.Delete(dir);}}),
        ("R2 sect work reserve setting and redemption use existing rules",()=>{var e=new SimulationEngine(World());Check(e.ExecutePlayerActivity(Cmd("accept-work",ActionKind.AcceptSectWork,"herb")).Accepted,"Work accept failed");var setting=Cmd("set-stock",ActionKind.SetSectStockReservation,"sect-stock") with {StockReservation=new(0,2)};Check(e.ExecutePlayerActivity(setting).Accepted,"Setting failed");Check(e.ExecutePlayerActivity(Cmd("buy-points",ActionKind.BuyContribution,"spirit-stone",10)).Accepted,"Purchase failed");Check(e.ExecutePlayerActivity(Cmd("redeem",ActionKind.RedeemContribution,"herb",2)).Accepted,"Redeem failed");var w=e.Snapshot();foreach(string id in new[]{"accept-work","set-stock","buy-points","redeem"})Check(w.Time!.ActionRuntime!.Actions[id].Phase==ActionPhase.Completed,"Missing completed action "+id);Check(w.SectFacilities!.ReservedHerbs==2&&w.SectWorkAssignments.Any(a=>a.ActorId=="player"&&a.ProductId=="herb")&&Inventory.Balance(w,"player","contribution")==10-2*w.SectFacilities.HerbExchangePrice,"Sect result changed");}),
        ("R2 contribution purchase fails when funds disappear and retains AP",()=>{var e=new SimulationEngine(World());var i=Cmd("points-fail",ActionKind.BuyContribution,"spirit-stone",10);e.Submit(i);e.AdvanceTo(0);var w=e.Snapshot();var a=w.Time!.ActionRuntime!.Actions[i.Id];long funds=Inventory.Balance(w,"player","spirit-stone");w.Ledger.Add(new(w.NextSequence++,w.Clock.Tick,"remove-funds","player","sect","spirit-stone",funds,"FixtureTransfer"));e=new SimulationEngine(w);e.AdvanceTo(a.DueAt);w=e.Snapshot();Check(w.Time!.ActionRuntime!.Actions[i.Id].Phase==ActionPhase.Failed&&w.Time.Charges.Count(c=>c.ActionId==i.Id)==1&&!w.Ledger.Any(l=>l.ActionId==i.Id&&l.Reason=="ContributionPurchasePayment"),"Failure transferred funds or refunded AP");})
    };
}
